#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Cat {
protected:
    string name;
    int age;
public:
    Cat(string n, int a) : name(n), age(a) {}
    void greet() {
        cout << "我是" << name << "，今年 " << age << " 岁喵" << endl;
    }
};

int main() {
    int n = 0;
    cin >> n;

    vector<Cat> roster;
    for (int i = 0; i < n; i++) {
        int cmd = 0;
        cin >> cmd;

        if (cmd == 0) {
            cout << "收摊喵，今天登记了 " << roster.size() << " 只" << endl;
            break;
        } else if (cmd == 1) {
            roster.push_back(Cat("{name}", {age}));
            cout << "登记了一只，名册上现在 " << roster.size() << " 只" << endl;
        } else if (cmd == 2) {
            int k = 0;
            for (Cat& c : roster) {
                k = k + 1;
                cout << k << ". ";
                c.greet();
            }
        } else {
            cout << "本喵还不会这个号码喵" << endl;
        }
    }
    cout << "号码走完了，名册上 " << roster.size() << " 只" << endl;
    return 0;
}
